1	/**
2	 * Bulk-import the real Steam Workshop catalogue into `GameMod` for the 9
3	 * families where a Workshop item genuinely installs on a Nxeon dedicated
4	 * server: ark, unturned, dst, squad, empyrion, soulmask, projectzomboid, tf2,
5	 * l4d2. Also imports palworld (Workshop is real upstream, just not wired to
6	 * an install button here — see docs/DOCUMENTATION.md's 2026-09-20 entry).
7	 * icarus is deliberately excluded: its dedicated server has no Steam Workshop
8	 * integration at all (confirmed against RocketWerkz's own dedicated-server
9	 * docs), and a live query against its appid (1149460) returns zero items
10	 * anyway — there is nothing real to import.
11	 *
12	 * SOURCE: Steam Web API's IPublishedFileService/QueryFiles/v1 — a real,
13	 * documented, key-gated endpoint (STEAM_WEB_API_KEY, already live in
14	 * production — confirmed today via ISteamWebAPIUtil/GetServerInfo/v1).
15	 * query_type=9 (k_PublishedFileQueryType_RankedByTotalUniqueSubscriptions)
16	 * sorts each family's items by subscriber count descending, so paging stops
17	 * the moment a page drops below the quality floor rather than walking the
18	 * whole catalogue.
19	 *
20	 * APPIDS: Steam Workshop items are filed under the game's CLIENT appid, not
21	 * a separate "dedicated server" appid — verified empirically against this
22	 * key (querying a guessed dedicated-server appid for every one of these
23	 * families returned total:0; the real client appid below is what actually
24	 * has items, cross-checked against store.steampowered.com/api/appdetails
25	 * for the exact title match):
26	 *   ark=346110 (ARK: Survival Evolved) unturned=304930 dst=322330
27	 *   squad=393380 empyrion=383120 soulmask=2646460 projectzomboid=108600
28	 *   tf2=440 l4d2=550 palworld=1623730
29	 *
30	 * QUALITY THRESHOLD: subscriptions >= 25 (default, override with
31	 * --min-subscriptions). Modrinth's own import script uses downloads>1000 OR
32	 * follows>50 because Modrinth's total catalogue is huge (~158k projects) and
33	 * dominated by noise; Steam Workshop per-family here is a completely
34	 * different shape — the smallest of these (Squad, ~301 total items as of
35	 * 2026-09-20) would be reduced to almost nothing under a four-figure floor,
36	 * while the largest (L4D2, ~220k total items) is exactly the kind of catalog
37	 * that floor exists to filter. 25 subscribers is deliberately low: it still
38	 * excludes the long tail of zero/single-digit-subscriber test uploads and
39	 * reuploads (sampled live: TF2's rank-9000 item sits at 4 subscribers) while
40	 * keeping every family's real, used content. Also requires `result === 1`
41	 * (OK — not banned/removed/pending) and `visibility === 0` (public).
42	 *
43	 * WHAT THIS DOES NOT FETCH: galleries (Workshop's `previews` array needs a
44	 * separate per-item call this bulk pass skips, same efficiency tradeoff as
45	 * Modrinth's importer deferring fileBytes/dependencyCount to
46	 * verify-gamemods.ts), and `license` (Steam Workshop items never carry one —
47	 * left null, per the architecture note: this is fetch-only/no-mirror content
48	 * so a license never applied in the first place).
49	 *
50	 * IDEMPOTENT: every write is `db.gameMod.upsert` on the real
51	 * `@@unique([gameFamily, slug])` constraint.
52	 *
53	 *   Dry run, one family, tiny slice:
54	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-steamworkshop-catalog.ts \
55	 *       --families=tf2 --max-pages=1
56	 *
57	 *   Real write, one family, tiny slice:
58	 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-steamworkshop-catalog.ts \
59	 *       --families=tf2 --max-pages=1 --apply
60	 *
61	 *   Full real run (all 10 families, default threshold):
62	 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-steamworkshop-catalog.ts --apply
63	 */
64	
65	import { assertDbTarget } from "./db-target-guard";
66	assertDbTarget("import-steamworkshop-catalog.ts");
67	
68	import { db } from "../lib/db";
69	
70	const STEAM_KEY = process.env.STEAM_WEB_API_KEY ?? "";
71	if (!STEAM_KEY) {
72	  console.error("STEAM_WEB_API_KEY is not set — refusing to run (see .env).");
73	  process.exit(1);
74	}
75	const API = "https://api.steampowered.com";
76	const PAGE_SIZE = 100; // Steam's real server-side cap on numperpage for this endpoint
77	const RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS = 9;
78	
79	const FAMILY_APPID: Record<string, number> = {
80	  ark: 346110,
81	  unturned: 304930,
82	  dst: 322330,
83	  squad: 393380,
84	  empyrion: 383120,
85	  soulmask: 2646460,
86	  projectzomboid: 108600,
87	  tf2: 440,
88	  l4d2: 550,
89	  palworld: 1623730,
90	};
91	const ALL_FAMILIES = Object.keys(FAMILY_APPID);
92	
93	// ── CLI args ──────────────────────────────────────────────────────────────
94	function parseArgs(argv: string[]) {
95	  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
96	  const familiesArg = get("families");
97	  const families = (familiesArg ? familiesArg.split(",") : ALL_FAMILIES).filter((f) => ALL_FAMILIES.includes(f));
98	  return {
99	    apply: argv.includes("--apply"),
100	    minSubscriptions: Number(get("min-subscriptions") ?? 25),
101	    maxPerFamily: Number(get("max-per-family") ?? 1000),
102	    ratePerMin: Number(get("rate-per-min") ?? 55), // Steam Web API's documented default cap is ~100k/day per key; stay well under any per-minute burst limit
103	    maxPages: get("max-pages") ? Number(get("max-pages")) : undefined,
104	    families: families.length ? families : ALL_FAMILIES,
105	  };
106	}
107	
108	// ── Rate-limited, retrying fetch (same shape as scripts/import-modrinth-catalog.ts) ──
109	class RateLimiter {
110	  private minIntervalMs: number;
111	  private last = 0;
112	  constructor(perMin: number) {
113	    this.minIntervalMs = 60_000 / perMin;
114	  }
115	  async wait() {
116	    const now = Date.now();
117	    const elapsed = now - this.last;
118	    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
119	    this.last = Date.now();
120	  }
121	}
122	
123	async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
124	  await limiter.wait();
125	  const res = await fetch(url, { headers: { "User-Agent": "Nxeon/1.0 (mods@nxeon.cloud)" } });
126	  if ((res.status === 429 || res.status >= 500) && attempt <= 5) {
127	    const backoffMs = 1000 * 2 ** attempt;
128	    console.warn(`  [retry] HTTP ${res.status} on ${url.replace(STEAM_KEY, "***")} — backing off ${Math.round(backoffMs / 1000)}s`);
129	    await new Promise((r) => setTimeout(r, backoffMs));
130	    return apiFetch(limiter, url, attempt + 1);
131	  }
132	  return res;
133	}
134	
135	// ── Steam types (only the fields we read) ────────────────────────────────
136	type PublishedFile = {
137	  result: number;
138	  publishedfileid: string;
139	  creator?: string;
140	  title?: string;
141	  short_description?: string;
142	  preview_url?: string;
143	  subscriptions?: number;
144	  banned?: boolean;
145	  visibility?: number;
146	  time_updated?: number;
147	};
148	type QueryFilesResponse = { response: { total?: number; publishedfileditails?: never; publishedfiledetails?: PublishedFile[] } };
149	type PlayerSummary = { steamid: string; personaname?: string; avatarfull?: string };
150	
151	function kebab(s: string): string {
152	  return s
153	    .toLowerCase()
154	    .replace(/[^a-z0-9]+/g, "-")
155	    .replace(/^-+|-+$/g, "")
156	    .slice(0, 60) || "workshop-item";
157	}
158	
159	type Counters = { seen: number; qualified: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
160	function emptyCounters(): Counters {
161	  return { seen: 0, qualified: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
162	}
163	
164	async function fetchAuthors(limiter: RateLimiter, steamIds: string[]): Promise<Map<string, PlayerSummary>> {
165	  const out = new Map<string, PlayerSummary>();
166	  const unique = [...new Set(steamIds.filter(Boolean))];
167	  for (let i = 0; i < unique.length; i += 100) {
168	    const slice = unique.slice(i, i + 100);
169	    const url = `${API}/ISteamUser/GetPlayerSummaries/v2/?key=${STEAM_KEY}&steamids=${slice.join(",")}`;
170	    const res = await apiFetch(limiter, url);
171	    if (!res.ok) continue;
172	    const body = (await res.json()) as { response?: { players?: PlayerSummary[] } };
173	    for (const p of body.response?.players ?? []) out.set(p.steamid, p);
174	  }
175	  return out;
176	}
177	
178	async function importFamily(opts: {
179	  family: string;
180	  appid: number;
181	  limiter: RateLimiter;
182	  apply: boolean;
183	  minSubscriptions: number;
184	  maxPerFamily: number;
185	  maxPages?: number;
186	}): Promise<Counters> {
187	  const { family, appid, limiter, apply, minSubscriptions, maxPerFamily, maxPages } = opts;
188	  const counters = emptyCounters();
189	  let cursor = "*";
190	  let page = 0;
191	  let total: number | undefined;
192	  const qualifiedBatch: PublishedFile[] = [];
193	
194	  for (;;) {
195	    if (maxPages !== undefined && page >= maxPages) break;
196	    if (counters.qualified >= maxPerFamily) break;
197	
198	    const url =
199	      `${API}/IPublishedFileService/QueryFiles/v1/` +
200	      `?key=${STEAM_KEY}&appid=${appid}&numperpage=${PAGE_SIZE}&cursor=${encodeURIComponent(cursor)}` +
201	      `&query_type=${RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS}&return_short_description=true&format=json`;
202	    const res = await apiFetch(limiter, url);
203	    page++;
204	    if (!res.ok) {
205	      console.error(`  [${family}] HTTP ${res.status} at page ${page} — stopping this family early`);
206	      break;
207	    }
208	    const body = (await res.json()) as QueryFilesResponse & { response: { next_cursor?: string } };
209	    const items = body.response.publishedfiledetails ?? [];
210	    total = body.response.total ?? total;
211	    counters.seen += items.length;
212	    if (items.length === 0) break;
213	
214	    let sawBelowFloor = false;
215	    for (const item of items) {
216	      if (item.result !== 1 || item.banned || (item.visibility ?? 0) !== 0) continue;
217	      const subs = item.subscriptions ?? 0;
218	      if (subs < minSubscriptions) {
219	        sawBelowFloor = true;
220	        break; // sorted descending by subscriptions — nothing after this qualifies either
221	      }
222	      if (!item.title || !item.publishedfileid) continue;
223	      qualifiedBatch.push(item);
224	      counters.qualified++;
225	      if (counters.qualified >= maxPerFamily) break;
226	    }
227	
228	    const nextCursor = (body.response as { next_cursor?: string }).next_cursor;
229	    console.log(
230	      `  [${family}] page=${page} fetched=${items.length} qualified_running=${counters.qualified} total=${total ?? "?"}`
231	    );
232	    if (sawBelowFloor || !nextCursor || nextCursor === cursor) break;
233	    cursor = nextCursor;
234	  }
235	
236	  if (qualifiedBatch.length === 0) {
237	    console.log(`  [${family}] nothing qualified (floor=${minSubscriptions} subscribers)`);
238	    return counters;
239	  }
240	
241	  if (!apply) {
242	    counters.upserted = qualifiedBatch.length;
243	    return counters;
244	  }
245	
246	  const authors = await fetchAuthors(limiter, qualifiedBatch.map((i) => i.creator ?? ""));
247	  const CONCURRENCY = 8;
248	  for (let i = 0; i < qualifiedBatch.length; i += CONCURRENCY) {
249	    const slice = qualifiedBatch.slice(i, i + CONCURRENCY);
250	    await Promise.all(
251	      slice.map(async (item) => {
252	        const publishedFileId = item.publishedfileid;
253	        const slug = `${kebab(item.title!)}-${publishedFileId.slice(-6)}`;
254	        const author = item.creator ? authors.get(item.creator) : undefined;
255	        const data = {
256	          name: item.title!,
257	          category: "Workshop",
258	          description: item.short_description || null,
259	          iconUrl: item.preview_url || null,
260	          url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${publishedFileId}`,
261	          downloads: item.subscriptions ?? null,
262	          license: null,
263	          serverSide: null,
264	          galleryUrls: [] as string[],
265	          authorName: author?.personaname ?? null,
266	          authorAvatarUrl: author?.avatarfull ?? null,
267	          source: "steam_workshop",
268	          sourceId: publishedFileId,
269	          active: true,
270	          verifiedAt: new Date(),
271	          upstreamOk: true,
272	          upstreamNote: null,
273	        };
274	        try {
275	          const existing = await db.gameMod.findUnique({
276	            where: { gameFamily_slug: { gameFamily: family, slug } },
277	            select: { id: true },
278	          });
279	          // select: { id: true } — a concurrent agent worktree sharing this
280	          // tree's node_modules regenerated the Prisma client against a schema
281	          // ahead of this database (a real `longDescription` column drift,
282	          // unrelated to this script); limiting the returned shape avoids
283	          // asking Postgres for a column this database doesn't have yet
284	          // rather than papering over it by touching the shared client.
285	          await db.gameMod.upsert({
286	            where: { gameFamily_slug: { gameFamily: family, slug } },
287	            update: data,
288	            create: { gameFamily: family, slug, ...data },
289	            select: { id: true },
290	          });
291	          counters.upserted++;
292	          if (existing) counters.updated++;
293	          else counters.created++;
294	        } catch (e) {
295	          counters.failed++;
296	          console.error(`  [db] ${family}/${slug} failed:`, e instanceof Error ? e.message : e);
297	        }
298	      })
299	    );
300	  }
301	  return counters;
302	}
303	
304	async function main() {
305	  const args = parseArgs(process.argv.slice(2));
306	  console.log(
307	    `[import-steamworkshop-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
308	      `families: ${args.families.join(", ")}; threshold: subscriptions>=${args.minSubscriptions}; ` +
309	      `max-per-family=${args.maxPerFamily}; rate=${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
310	  );
311	
312	  const limiter = new RateLimiter(args.ratePerMin);
313	  const totals = emptyCounters();
314	  const perFamily: Record<string, Counters> = {};
315	
316	  for (const family of args.families) {
317	    console.log(`\n=== ${family} (appid ${FAMILY_APPID[family]}) ===`);
318	    const counters = await importFamily({
319	      family,
320	      appid: FAMILY_APPID[family],
321	      limiter,
322	      apply: args.apply,
323	      minSubscriptions: args.minSubscriptions,
324	      maxPerFamily: args.maxPerFamily,
325	      maxPages: args.maxPages,
326	    });
327	    perFamily[family] = counters;
328	    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
329	    console.log(
330	      `--- ${family} done: seen=${counters.seen} qualified=${counters.qualified} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} failed=${counters.failed} ---`
331	    );
332	  }
333	
334	  console.log(`\n============================================================`);
335	  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
336	  for (const family of args.families) {
337	    const c = perFamily[family]!;
338	    console.log(
339	      `  ${family.padEnd(15)} seen=${c.seen.toString().padStart(6)} qualified=${c.qualified.toString().padStart(5)} upserted=${c.upserted.toString().padStart(5)} created=${c.created.toString().padStart(5)} updated=${c.updated.toString().padStart(5)} failed=${c.failed}`
340	    );
341	  }
342	  console.log(
343	    `  ${"TOTAL".padEnd(15)} seen=${totals.seen.toString().padStart(6)} qualified=${totals.qualified.toString().padStart(5)} upserted=${totals.upserted.toString().padStart(5)} created=${totals.created.toString().padStart(5)} updated=${totals.updated.toString().padStart(5)} failed=${totals.failed}`
344	  );
345	}
346	
347	main()
348	  .then(() => process.exit(0))
349	  .catch((e) => {
350	    console.error(e);
351	    process.exit(1);
352	  });
353

1	/**
2	 * Refuse to write to a database nobody deliberately pointed us at.
3	 *
4	 * ---------------------------------------------------------------------------
5	 * THE INCIDENT THIS EXISTS FOR (2026-07-26)
6	 * ---------------------------------------------------------------------------
7	 * An agent ran `prisma/seed.ts` from a scratch working tree. That tree had its
8	 * `node_modules` SYMLINKED to /opt/nxeon/node_modules, so `@prisma/client`
9	 * resolved through the symlink, and Prisma's dotenv loader walked up from the
10	 * REAL module location and loaded `/opt/nxeon/.env` — the PRODUCTION env. The
11	 * seed therefore connected to the production database `nxeon` while every human
12	 * signal (the cwd, the checkout, the intent) said "scratch".
13	 *
14	 * It happened to be a pure `upsert` seed, so it did no damage. That is luck, not
15	 * a control. The same accident with `prisma db push --accept-data-loss`, or with
16	 * a seed that had grown a `deleteMany`, destroys a live hosting platform's
17	 * customer records.
18	 *
19	 * The root cause is NOT "the seed was careless". It is that a writing script
20	 * inherits its target from ambient environment resolution — a mechanism with no
21	 * confirmation step, which resolves silently and can be wrong for reasons that
22	 * are invisible at the call site (a symlink three directories away).
23	 *
24	 * ---------------------------------------------------------------------------
25	 * THE CONTROL
26	 * ---------------------------------------------------------------------------
27	 * A writing script must state, out loud, which database it believes it is about
28	 * to write to. The operator states it independently, via `NXEON_DB_TARGET`. The
29	 * script runs only if the two agree.
30	 *
31	 *     NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed.ts
32	 *
33	 * This is deliberately NOT a "--force"/"--yes" flag. A blanket confirmation
34	 * answers "do you want to proceed?", and in the incident above the honest answer
35	 * was yes — the operator did want to seed, just not THAT database. Naming the
36	 * target answers the question that was actually wrong. An operator who types
37	 * `NXEON_DB_TARGET=nxeon_scratch` while the environment silently resolves to
38	 * `nxeon` gets a refusal and a diff, which is exactly the moment the symlink
39	 * becomes visible.
40	 *
41	 * Pure and side-effect free so it can be unit-tested without a database; see
42	 * test/db-target-guard.test.ts.
43	 */
44	
45	/** Environment variable through which the operator names the intended database. */
46	export const TARGET_ENV_VAR = "NXEON_DB_TARGET";
47	
48	export type DbTargetDecision =
49	  | { allowed: true; database: string }
50	  | { allowed: false; database: string | null; message: string };
51	
52	/**
53	 * Extract the database NAME from a PostgreSQL connection URL.
54	 *
55	 * Returns null when the URL is absent, unparseable, or names no database. We do
56	 * not guess: a connection string we cannot read is a connection string we cannot
57	 * confirm, and the whole point here is to stop acting on unconfirmed targets.
58	 */
59	export function databaseNameFromUrl(url: string | undefined | null): string | null {
60	  if (!url) return null;
61	  let parsed: URL;
62	  try {
63	    parsed = new URL(url);
64	  } catch {
65	    return null;
66	  }
67	  if (!/^postgres(ql)?:$/.test(parsed.protocol)) return null;
68	  // pathname is "/dbname" (or "" / "/" when no database is named).
69	  const raw = parsed.pathname.replace(/^\//, "");
70	  if (!raw) return null;
71	  let name: string;
72	  try {
73	    name = decodeURIComponent(raw);
74	  } catch {
75	    // A malformed percent-escape means we cannot say what database this is.
76	    return null;
77	  }
78	  return name || null;
79	}
80	
81	/**
82	 * Decide whether a writing script may proceed.
83	 *
84	 * `declared` is what the operator said (NXEON_DB_TARGET); `databaseUrl` is what
85	 * the environment silently resolved to. They must agree.
86	 */
87	export function decideDbTarget(opts: {
88	  databaseUrl: string | undefined | null;
89	  declared: string | undefined | null;
90	  /** Script name, used only to make the refusal message copy-pasteable. */
91	  script: string;
92	}): DbTargetDecision {
93	  const { databaseUrl, declared, script } = opts;
94	  const resolved = databaseNameFromUrl(databaseUrl);
95	
96	  if (!databaseUrl) {
97	    return {
98	      allowed: false,
99	      database: null,
100	      message:
101	        `Refusing to run ${script}: DATABASE_URL is not set.\n` +
102	        `Nothing was written. Set DATABASE_URL and ${TARGET_ENV_VAR} to the same database.`,
103	    };
104	  }
105	
106	  if (!resolved) {
107	    return {
108	      allowed: false,
109	      database: null,
110	      message:
111	        `Refusing to run ${script}: DATABASE_URL does not name a PostgreSQL database.\n` +
112	        `Nothing was written. Could not determine a database name from the connection string,\n` +
113	        `so there is no target to confirm against ${TARGET_ENV_VAR}.`,
114	    };
115	  }
116	
117	  const want = (declared ?? "").trim();
118	  if (!want) {
119	    return {
120	      allowed: false,
121	      database: resolved,
122	      message:
123	        `Refusing to run ${script}: ${TARGET_ENV_VAR} is not set.\n` +
124	        `Nothing was written.\n\n` +
125	        `This environment resolves to the database: ${resolved}\n\n` +
126	        `If that is genuinely the database you meant to write to, say so explicitly:\n` +
127	        `    ${TARGET_ENV_VAR}=${resolved} <your command>\n\n` +
128	        `Check it first. DATABASE_URL is resolved from a .env file that dotenv finds by\n` +
129	        `walking up from the Prisma client's REAL location — which, if node_modules is a\n` +
130	        `symlink, is not the tree you are standing in.`,
131	    };
132	  }
133	
134	  if (want !== resolved) {
135	    return {
136	      allowed: false,
137	      database: resolved,
138	      message:
139	        `Refusing to run ${script}: the database does not match what you asked for.\n` +
140	        `Nothing was written.\n\n` +
141	        `  ${TARGET_ENV_VAR} (what you asked for)  : ${want}\n` +
142	        `  DATABASE_URL    (what it resolved to): ${resolved}\n\n` +
143	        `These disagree, so one of them is wrong and it is not safe to guess which.\n` +
144	        `The usual cause is a .env being picked up from a different tree than the one you\n` +
145	        `are working in (a symlinked node_modules will do it). Confirm with:\n` +
146	        `    node -e 'console.log(process.env.DATABASE_URL)'`,
147	    };
148	  }
149	
150	  return { allowed: true, database: resolved };
151	}
152	
153	/**
154	 * Enforce the decision, or exit non-zero having written nothing.
155	 *
156	 * Exits rather than throwing: a throw from a top-level `main()` that lacks a
157	 * `.catch` becomes an unhandled rejection, which prints a stack trace and buries
158	 * the one sentence the operator needs to read.
159	 */
160	export function assertDbTarget(script: string): string {
161	  const decision = decideDbTarget({
162	    databaseUrl: process.env.DATABASE_URL,
163	    declared: process.env[TARGET_ENV_VAR],
164	    script,
165	  });
166	  if (!decision.allowed) {
167	    console.error(`\n${decision.message}\n`);
168	    process.exit(1);
169	  }
170	  console.log(`[${script}] target database confirmed: ${decision.database}`);
171	  return decision.database;
172	}
