151	    gameFamily: m.gameFamily,
152	    gameFamilyLabel: familyLabel(m.gameFamily),
153	    name: m.name,
154	    slug: m.slug,
155	    category: m.category,
156	    source: m.source,
157	    iconUrl: m.iconUrl,
158	    description: m.description,
159	    downloads: m.downloads,
160	    featured: m.featured,
161	    paid: m.paid,
162	    verified: m.verifiedAt !== null,
163	    impact: m.impact,
164	    createdAt: m.createdAt.toISOString(),
165	    avgRating: agg?.avg ?? null,
166	    ratingCount: agg?.count ?? 0,
167	    url: m.url,
168	    sourceId: m.sourceId,
169	    appliesToVariant: m.appliesToVariant,
170	    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
171	  };
