199	  async (): Promise<{ family: string; label: string; count: number }[]> => {
200	    const rows = await db.gameMod.groupBy({
201	      by: ["gameFamily"],
202	      where: { active: true, upstreamOk: true },
203	      _count: true,
204	      orderBy: { gameFamily: "asc" },
205	    });
206	    return rows
207	      .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
