320	/**
321	 * Curated "Most downloaded" rail — real `GameMod.downloads`, DB-side sorted
322	 * and DB-side filtered to `downloads: { not: null }`. That filter matters:
323	 * Postgres' default NULLS FIRST for a DESC sort would otherwise put every
324	 * never-verified (downloads: null) row ahead of real numbers — see the
325	 * `rust`/`cs2` families, which currently have zero mods with a real
326	 * `downloads` count and so correctly return an empty array here rather than
327	 * a page of nulls masquerading as "most downloaded". Omit `family` for a
328	 * cross-game rail (the NxLabs homepage's curated section).
329	 */
330	export async function listTopDownloadedMods(family?: string, take = 8): Promise<ModSummary[]> {
331	  const rows = await db.gameMod.findMany({
332	    where: { active: true, upstreamOk: true, downloads: { not: null }, ...(family ? { gameFamily: family } : {}) },
333	    orderBy: [{ downloads: "desc" }, { name: "asc" }],
334	    take,
335	  });
336	  const aggs = await ratingAggs(rows.map((r) => r.id));
337	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
338	}
