340	/**
341	 * Curated "Recently updated" rail — real `GameMod.upstreamUpdatedAt` only,
342	 * DB-side sorted desc and filtered to non-null. That filter is the whole
343	 * point: `upstreamUpdatedAt` is backfilled from each source's OWN API
344	 * (scripts/backfill-upstream-updated.ts), never derived from this table's
345	 * own `updatedAt` (which just marks when WE last touched the row — a bulk
346	 * re-import, a verify pass — and says nothing about the mod's real upstream
347	 * freshness). A mod that hasn't been backfilled yet has `upstreamUpdatedAt:
348	 * null` and simply doesn't appear here — never padded in with a guess.
349	 * Omit `family` for a cross-game rail (the NxLabs homepage's curated
350	 * section), same convention as listTopDownloadedMods above.
351	 */
352	export async function listRecentlyUpdatedMods(family?: string, take = 8): Promise<ModSummary[]> {
353	  const rows = await db.gameMod.findMany({
354	    where: { active: true, upstreamOk: true, upstreamUpdatedAt: { not: null }, ...(family ? { gameFamily: family } : {}) },
355	    orderBy: [{ upstreamUpdatedAt: "desc" }],
356	    take,
357	  });
358	  const aggs = await ratingAggs(rows.map((r) => r.id));
359	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
360	}
