362	/**
363	 * Curated "Top Rated" rail (item 6 of the 2026-09-20 NxLabs overhaul — the
364	 * fourth curated row alongside Featured/Most Downloaded/Recently Updated).
365	 * Checked first, per that task's own instruction: `ORDER_BY.rating` above
366	 * already exists and is StoreBrowser's real, documented "Top Rated" sort for
367	 * pagination — fetch by real downloads, then re-sort by real `avgRating`
368	 * within that fetched set, because there is no cached avgRating column to
369	 * order by at the DB level (see that constant's own comment). This rail
370	 * reuses the EXACT same query/approximation rather than a stricter
371	 * "real average across a minimum rating count" query, which would render
372	 * this row permanently empty everywhere: confirmed live 2026-09-20, the
373	 * `ModRating` table has zero rows catalogue-wide today. Reusing the same
374	 * approximation means the row and its "View more" (?sort=rating) destination
375	 * never disagree, and the moment any mod gets real ratings, it sorts to the
376	 * front here exactly as it would on that sort's page 1 — never a fabricated
377	 * ranking, just an honestly-labeled approximation until real rating volume
378	 * exists.
379	 */
380	export async function listTopRatedMods(family?: string, take = 8): Promise<ModSummary[]> {
381	  const rows = await db.gameMod.findMany({
382	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
383	    orderBy: ORDER_BY.rating,
384	    take: take * 3, // over-fetch so the real-rating re-sort below has room to surface any rated mods
385	  });
386	  const aggs = await ratingAggs(rows.map((r) => r.id));
387	  return rows
388	    .map((r) => toSummary(r, aggs.get(r.id)))
389	    .sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount)
390	    .slice(0, take);
391	}
