459	export async function listModComments(modId: string, opts: { take?: number; cursor?: string } = {}): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
460	  const take = opts.take ?? 10;
461	  const rows = await db.modRating.findMany({
462	    where: { gameModId: modId, comment: { not: null } },
463	    orderBy: { createdAt: "desc" },
464	    take: take + 1,
465	    ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : {}),
466	    include: { user: { select: { id: true, name: true } } },
467	  });
468	  const page = rows.slice(0, take);
469	  const nextCursor = rows.length > take ? page[page.length - 1]!.id : null;
470	  return {
471	    comments: page.map((r) => ({
472	      id: r.id,
473	      rating: r.rating,
474	      comment: r.comment!,
475	      createdAt: r.createdAt.toISOString(),
476	      userId: r.userId,
477	      userName: r.user.name,
478	    })),
479	    nextCursor,
