489	/**
490	 * `id` is the real, live `GamePlan.id` this recommendation resolved to — kept
491	 * on the result (not just derived data) so a caller can hand it straight to
492	 * `deployHref({ gamePlanId })` and land the wizard on this EXACT plan, the
493	 * same real-tier resolution `order.tsx`'s `orderFromIntent` already does for
494	 * a `tier` query param. Never a synthetic id — always one of the
495	 * `gamePlans` rows passed in below.
496	 */
497	export type RecommendedPlan = { id: string; planName: string; ramMB: number; priceCents: number } | null;
498	
499	/**
500	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
501	 * light-impact mods run on any active plan for the family; moderate needs at
502	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
503	 * for the family that clears the bar, or null if none does (never guesses a
504	 * number that isn't a real, active, orderable plan). `null` is also the
505	 * honest signal for a family with zero active GamePlan rows at all (e.g.
506	 * "schedule1", which has no official dedicated server and stays unseeded —
507	 * see lib/games.ts) — callers must not render a deploy action in that case.
508	 */
509	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "id" | "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
510	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
511	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
512	  const pick = candidates[0];
513	  return pick ? { id: pick.id, planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
514	}
515	
516	export function formatDownloads(n: number | null): string | null {
517	  if (n == null) return null;
518	  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(n >= 10_000_000_000 ? 0 : 1)}B`;
519	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
520	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
521	  return String(n);
522	}
523	
524	/** Same cents->"$X"/"$X.XX" convention as lib/vps-price-band.ts's money() — a real GamePlan.priceCents, never a hand-typed price string. */
525	export function formatPriceCents(cents: number): string {
526	  const v = cents / 100;
527	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
528	}
529	
530	/**
531	 * An honest, field-derived description for the small slice of active mods
532	 * with neither a real `description` tagline nor a `longDescription` body —
533	 * confirmed live 2026-09-20 (NxLabs overhaul, item 4): 148 of 45,766 active
534	 * mods (0.3%; mostly minimal Steam Workshop skin/map submissions and a
535	 * couple of GitHub repos with a blank `description` field) have nothing at
536	 * all from their source. This is composed only from real columns already on
537	 * the row — category, game, loader/variant, a game version, file size —
538	 * never invented marketing copy. `mod.description` and `mod.longDescription`
539	 * both being empty is the ONLY case that should ever reach this; callers
540	 * must prefer the real fields first.
541	 *
542	 * Separately: the much larger gap — 94.9% of active mods (all 32,243
543	 * Modrinth rows) have a real `description` tagline but no `longDescription`
544	 * — is NOT what this function is for. That gap exists because
545	 * scripts/backfill-modrinth-descriptions.ts, which fetches Modrinth's real
546	 * project `body` and is fully idempotent/rate-limited, has only ever been
547	 * run as a dry run against production, never with `--apply`. That is a
548	 * one-time data-backfill run to do, not a rendering fallback — see this
549	 * task's final report.
550	 */
551	export function composedDescriptionFor(
552	  mod: Pick<ModDetail, "category" | "gameFamilyLabel" | "loaders" | "appliesToVariant" | "gameVersions" | "fileBytes">
553	): string {
554	  const bits = [`A ${mod.category} for ${mod.gameFamilyLabel}`];
555	  const platform = mod.loaders[0] ?? mod.appliesToVariant;
556	  if (platform) bits.push(platform);
557	  const version = mod.gameVersions[mod.gameVersions.length - 1];
558	  if (version) bits.push(`version ${version}`);
559	  let text = `${bits.join(", ")}.`;
560	  const size = formatBytes(mod.fileBytes);
561	  if (size) text += ` ${size} download.`;
562	  return text;
563	}
564	
565	export function formatBytes(bytes: number | null): string | null {
566	  if (!bytes || bytes <= 0) return null;
567	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
568	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
569	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
570	}
571	
572	export type ResolvedDownload = { url: string; direct: boolean } | null;
573	
574	/**
575	 * The synchronous half of download resolution — every source EXCEPT
576	 * modrinth/thunderstore resolves with no network call at all (spigotmc's
577	 * Spiget endpoint is a constructed URL, everything else is just `mod.url`).
578	 * Returns `undefined` for modrinth/thunderstore specifically, meaning "a
579	 * live external API call is required" — callers that can't afford to block
580	 * on that (see StoreBrowser.tsx) use this to render immediately for the
581	 * ~50% of the catalogue that needs no network at all, and defer the rest to
582	 * an on-demand client resolve.
583	 *
584	 * REAL PERFORMANCE FIX (2026-09-21): `resolveDownloadUrl` below used to be
585	 * called via `Promise.all` for EVERY mod card in StoreBrowser's grid (up to
586	 * `CATALOG_PAGE_SIZE`=24 per /mods and /dashboard/nxlabs page load). That was
587	 * a real, harmless-looking pattern when the catalogue was ~124 hand-seeded
588	 * rows with few resolvable `sourceId`s; the moment the Modrinth bulk import
589	 * landed 32,000+ real rows, most default/browse pages became Modrinth-
590	 * dominated, and every single page load started firing up to 24 concurrent,
591	 * uncached, un-timed-out HTTPS calls to api.modrinth.com as part of server
592	 * rendering — measured live against production at 1-2.2s of REAL added
593	 * latency per page load (see docs/DOCUMENTATION.md's 2026-09-21 entry for
594	 * the exact numbers), with no upper bound if Modrinth itself is ever slow.
595	 * Splitting the sync-resolvable 50%+ of sources out, and deferring the
596	 * network-bound rest to a click-triggered resolve (DownloadButton.tsx +
597	 * lib/actions-mods.ts's resolveModDownloadAction), removes ALL of that from
598	 * the server-render critical path — a card the visitor never clicks now
599	 * costs zero external requests, instead of one whether it's clicked or not.
600	 */
601	export function resolveDownloadUrlSync(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): ResolvedDownload | undefined {
602	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
603	  const id = mod.sourceId ?? "";
604	  if (!id) return fallback;
605	  if (mod.source === "modrinth" || mod.source === "thunderstore") return undefined;
606	  if (mod.source === "spigotmc") {
607	    // Spiget's own download endpoint 302s to the real jar — genuinely direct, no fetch needed to know that.
608	    return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
609	  }
610	  return fallback;
611	}
612	
613	/**
614	 * The uncached live-fetch half of `resolveDownloadUrl` below — pulled out on
615	 * its own so `unstable_cache` (see `resolveDownloadUrlCached`) wraps ONLY the
616	 * tiny resolved `{url, direct}` result, never the raw upstream response body.
617	 *
618	 * REAL BUG FIX (2026-09-22): this used to rely on `next: { revalidate: 3600 }`
619	 * on the `fetch` calls themselves — Next's fetch data-cache, which silently
620	 * refuses to store any response over roughly 2MB and simply re-fetches live
621	 * on every call instead, with no error or warning. Confirmed live via
622	 * journalctl: `minecraft-comes-alive-reborn`'s Modrinth `/version` response is
623	 * 20,035,322 bytes, so it was being re-fetched from api.modrinth.com on
624	 * EVERY single visit to that mod's detail page with zero caching benefit —
625	 * and Modrinth's version-list responses routinely run large for mods with
626	 * many released files, so this wasn't an isolated case. The actual value we
627	 * need to cache is a couple hundred bytes (`{url, direct}`); caching that
628	 * directly via `unstable_cache` sidesteps the fetch-cache size ceiling
629	 * entirely, for every mod regardless of how large its upstream response is.
630	 */
631	async function fetchLiveDownload(source: string, sourceId: string): Promise<{ url: string; direct: boolean } | null> {
632	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
633	  try {
634	    if (source === "modrinth") {
635	      const headers: Record<string, string> = { "User-Agent": UA };
636	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
637	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, {
638	        headers,
639	        signal: AbortSignal.timeout(5000),
640	      });
641	      if (!res.ok) return null;
642	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
643	      const v = versions[0];
644	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
645	      return file ? { url: file.url, direct: true } : null;
646	    }
647	    if (source === "thunderstore") {
648	      const [namespace, ...rest] = sourceId.split("-");
649	      if (!namespace || !rest.length) return null;
650	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
651	        headers: { "User-Agent": UA },
652	        signal: AbortSignal.timeout(5000),
653	      });
654	      if (!res.ok) return null;
655	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
656	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : null;
657	    }
658	  } catch {
659	    return null;
660	  }
661	  return null;
662	}
663	
664	const fetchLiveDownloadCached = unstable_cache(fetchLiveDownload, ["mods-catalog:resolveDownloadUrl"], {
665	  revalidate: 3600,
666	});
667	
668	/**
669	 * The real, authoritative download for a mod detail page. Prefers the
670	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
671	 * install it) so a visitor gets the actual file, not just a landing page;
672	 * falls back to the mod's own project/resource page (still the real,
673	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
674	 * be resolved live or isn't one of the three we know how to resolve.
675	 *
676	 * Fine to call eagerly for ONE mod (the detail pages do exactly that) — the
677	 * cost that mattered was calling it for a whole page of cards at once, see
678	 * `resolveDownloadUrlSync` above. Every live fetch carries a 5s timeout
679	 * (`AbortSignal.timeout`) so a slow/unresponsive upstream can never hang this
680	 * past a bounded worst case — there was no timeout at all before 2026-09-21,
681	 * so a degraded Modrinth/Thunderstore response could block a caller
682	 * indefinitely. The live fetch itself is cached via `unstable_cache`, not
683	 * `next: { revalidate }` — see `fetchLiveDownload`'s comment for why.
684	 */
685	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<ResolvedDownload> {
686	  const sync = resolveDownloadUrlSync(mod);
687	  if (sync !== undefined) return sync;
688	
689	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
690	  const id = mod.sourceId ?? "";
691	  const live = await fetchLiveDownloadCached(mod.source, id);
692	  return live ?? fallback;
693	}
