const GAME_FAMILY = "vintagestory";
const SOURCE = "vintagestory_moddb";

const DEFAULT_MIN_DOWNLOADS = 1000;
const DEFAULT_RATE_LIMIT_PER_MIN = 90; // conservative — VS documents no explicit ceiling
const GALLERY_CAP = 8; // matches the Modrinth/mod.io convention

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  return {
    apply: argv.includes("--apply"),
