  console.log(
    `  side=client excluded: ${counters.clientOnly}; side=server/both: ${serverRelevant.length}; ` +
      `eligible (downloads>${args.minDownloads}): ${counters.eligible}; processing ${slice.length}`
  );

  // Preload existing vintagestory_moddb rows — sourceId → row, for the same
  // match-by-immutable-id-first identity strategy as import-modio-catalog.ts.
  const existingRows = await db.gameMod.findMany({
    where: { gameFamily: GAME_FAMILY, source: SOURCE },
    select: { id: true, slug: true, sourceId: true },
  });
  const existingBySourceId = new Map(existingRows.filter((r) => r.sourceId).map((r) => [r.sourceId as string, r]));
  const usedSlugs = new Set(existingRows.map((r) => r.slug));
  console.log(`  ${existingRows.length} existing ${SOURCE} row(s) already in this family`);

  const CONCURRENCY = 5;
  for (let i = 0; i < slice.length; i += CONCURRENCY) {
    const batch = slice.slice(i, i + CONCURRENCY);
    await Promise.all(
      batch.map(async (summary) => {
        const detailRes = await apiFetch(limiter, `${API}/mod/${encodeURIComponent(summary.urlalias)}`);
        if (!detailRes.ok) {
          counters.failed++;
          console.error(`  [detail] ${summary.urlalias} → HTTP ${detailRes.status}`);
          return;
        }
        const detailBody = (await detailRes.json()) as VsDetailResponse;
        const mod = detailBody.mod;
        if (!mod) {
          counters.failed++;
          console.error(`  [detail] ${summary.urlalias} → no "mod" in response`);
          return;
        }

        const latestRelease = mod.releases?.[mod.releases.length - 1];
        const category = mod.tags?.[0] || "Mod";
        const data = {
          name: mod.name,
          category,
          description: summary.summary || null,
          longDescription: mod.text || null,
          iconUrl: mod.logofile || null,
          url: `https://mods.vintagestory.at/${mod.urlalias}`,
          downloads: mod.downloads,
          license: null,
          gameVersions: latestRelease?.tags ?? [],
          loaders: [] as string[],
          serverSide: serverSideFor(mod.side),
          galleryUrls: galleryUrlsFrom(mod.screenshots),
          authorName: mod.author || null,
          authorAvatarUrl: null,
          source: SOURCE,
          sourceId: String(mod.modid),
          active: true,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote: null as string | null,
        };

        if (!args.apply) {
          counters.upserted++;
          return;
        }

        const existing = existingBySourceId.get(String(mod.modid));
        try {
          if (existing) {
            await db.gameMod.update({ where: { id: existing.id }, data });
            counters.updated++;
          } else {
            let slug = mod.urlalias;
            for (let attempt = 0; attempt < 3 && usedSlugs.has(slug); attempt++) {
              slug = attempt === 0 ? `${mod.urlalias}-${mod.modid}` : `${mod.urlalias}-${mod.modid}-${attempt}`;
            }
            usedSlugs.add(slug);
            await db.gameMod.create({ data: { gameFamily: GAME_FAMILY, slug, ...data } });
            counters.created++;
          }
          counters.upserted++;
        } catch (e) {
          counters.failed++;
          const msg = e instanceof Error ? e.message : String(e);
          console.error(`  [db] failed to upsert ${summary.urlalias}: ${msg}`);
        }
      })
    );
    if ((i / CONCURRENCY) % 20 === 0) {
      console.log(
        `  progress: ${Math.min(i + CONCURRENCY, slice.length)}/${slice.length} processed ` +
          `(upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} failed=${counters.failed})`
      );
    }
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  console.log(
    `  vintagestory total=${counters.total} clientOnlyExcluded=${counters.clientOnly} belowFloor=${counters.belowFloor} ` +
      `eligible=${counters.eligible} processed=${slice.length} upserted=${counters.upserted} created=${counters.created} ` +
      `updated=${counters.updated} failed=${counters.failed}`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

