 * Checked live: `category:"internal"` (543 of 23,460) is a real, named
 * Mod Portal category, not a guess — sampled it (top hit "Finale": "Allows
 * arbitrary code execution during the data stage via mod settings. Intended
 * for modpack configuration.") and it is genuinely author-tooling for OTHER
 * mod/modpack authors, not consumer server content, matching this repo's
 * principle of only filtering where the source draws a real distinction.
 * `category:"no-category"` mods are KEPT — checked live, real popular mods
 * with no category tag exist (e.g. "Avatars", 13,362 downloads), so treating
 * an empty category as disqualifying would throw away real content the same
 * way excluding Modrinth's "unknown" environment for plugins would (see that
 * script's own header). downloads_count>1000 lands at 5,189 real mods after
 * the internal-category exclusion — top mods run 600k-1M+ (flib,
 * alien-biomes, informatron, jetpack), a real meaningful cut.
 *
 * FIELD NOTES (per-mod `/full` detail call):
 *   - `description` = the list endpoint's own `summary` (zero extra calls).
 *   - `longDescription` = `/full`'s `description` — real author-written
 *     markdown-ish text (confirmed live: Krastorio2's is 6,480 chars vs a
 *     124-char summary) — stored as-is, sanitized at render time, same
 *     convention as every other source's raw body in this repo.
 *   - `category` = the list endpoint's `category` (a fixed, real Mod Portal
 *     taxonomy: content/tweaks/utilities/mod-packs/overhaul/localizations/
 *     scenarios/no-category), falling back to the literal "Mod" only for the
 *     "no-category" value so the catalogue never shows a raw source-internal
 *     string as a category label.
 *   - `iconUrl` = `/full`'s `thumbnail` (a path, e.g.
 *     `/assets/<hash>.thumb.png`) resolved against the real asset host
 *     `https://assets-mod.factorio.com` — checked live this is where the
 *     Mod Portal's own thumbnails actually resolve (HTTP 200), NOT
 *     mods.factorio.com itself (HTTP 404 for the same path) — confirmed via
 *     wiki.factorio.com/Mod_portal_API and a live fetch. Null when a mod
 *     ships no thumbnail (checked live, genuinely happens).
 *   - `galleryUrls` = `/full`'s `images[].thumbnail`/`url`, same asset-host
 *     resolution, capped at GALLERY_CAP — empty for the large majority of
 *     mods checked live (the Mod Portal's screenshot feature is lightly
 *     used), never padded.
 *   - `license` = `/full`'s `license.title` (a real human-readable name, e.g.
 *     "GNU LGPLv3") when present, else `license.name`, else null — never
 *     fabricated; Factorio's own SPDX-ish id lives at `license.id` but
 *     `.title` matches this repo's "human-readable string" convention for
 *     the `license` column (compare Modrinth's `license.id` vs name usage).
 *   - `gameVersions` = every real Factorio version keyed in `/full`'s
 *     `releases[].info_json.factorio_version`, deduped — a real per-release
 *     compatibility field, not guessed from the mod's own metadata.
 *   - `upstreamUpdatedAt` = `/full`'s real `updated_at` timestamp — the Mod
 *     Portal publishes this per mod (confirmed live), so this importer
 *     populates it directly rather than leaving it for a later backfill
 *     pass, unlike sources where no such field exists.
 *   - `authorName` = `/full`'s `owner` (a plain string; the Mod Portal API
 *     has no author-avatar concept anywhere) — `authorAvatarUrl` always null.
 *   - `serverSide` = always null. Checked live: the Mod Portal draws no
 *     client/server distinction anywhere in its schema (no equivalent to
 *     Modrinth's `environment` or mod.io's "Application Type" tag group) —
 *     Factorio mods are near-universally needed on both sides for a
 *     multiplayer game to even connect, so there is no real signal to derive
 *     this from; left null/unknown rather than guessed "required" for all.
 *   - `fileBytes` / `dependencyCount` = left at their schema defaults
 *     (null / 0) — no byte size in either response, and `/full`'s
 *     `releases[].dependencies` exists but parsing Factorio's own dependency
 *     string grammar (`? optional-name >= 1.0.0`, `! incompatible-name`,
 *     etc.) into a real count is exactly verify-gamemods.ts-shaped follow-up
 *     work, not this bulk pass's job — matches the "WHAT THIS DOES NOT
 *     FETCH" convention every other importer in this repo documents.
 *
 * IDEMPOTENT: `db.gameMod.upsert` on the real `@@unique([gameFamily, slug])`
 * constraint. Identity: the Mod Portal's real immutable key is the mod's
 * `name` field itself (its internal identifier, distinct from the
 * human-readable `title` — confirmed live neither changes independently of
 * the other in the API's own data model the way Modrinth's slug can drift
 * from a project id), so `slug` is a kebab-cased version of `name` and
 * `sourceId` is the real `name` — matched on (gameFamily, source:
 * "factorio_portal", sourceId) first, same as every other importer here.
 *
 * SAFETY: dry run by default; `scripts/db-target-guard.ts` enforces
 * NXEON_DB_TARGET, same as every other writing script in this repo.
 *
 *   Dry run, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-factorio-catalog.ts \
 *       --max-items=20
 *
 *   Real write, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-factorio-catalog.ts \
 *       --max-items=20 --apply
 *
 *   Full real run (5,189 detail calls — will take a while at the conservative
 *   default rate; that is expected, same as this repo's other large pulls):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-factorio-catalog.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-factorio-catalog.ts");

import { db } from "../lib/db";

const API = "https://mods.factorio.com/api";
const ASSET_HOST = "https://assets-mod.factorio.com";
const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const GAME_FAMILY = "factorio";
const SOURCE = "factorio_portal";

const DEFAULT_MIN_DOWNLOADS = 1000;
const DEFAULT_RATE_LIMIT_PER_MIN = 90; // conservative — no documented ceiling found
const GALLERY_CAP = 8; // matches this repo's convention elsewhere

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  return {
    apply: argv.includes("--apply"),
    minDownloads: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS),
    ratePerMin: Number(get("rate-per-min") ?? DEFAULT_RATE_LIMIT_PER_MIN),
    maxItems: get("max-items") ? Number(get("max-items")) : undefined, // smoke-test cap, not a real-run knob
  };
}

// ── Rate-limited, retrying fetch (same pattern as the rest of this repo) ──
class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const now = Date.now();
    const elapsed = now - this.last;
    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    this.last = Date.now();
  }
}

async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const res = await fetch(url, { headers: { "User-Agent": UA } });
  if ((res.status === 429 || res.status >= 500) && attempt <= 5) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [retry] HTTP ${res.status} on ${url} — backing off ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

function kebab(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60) || "mod"
  );
}

// ── Factorio Mod Portal types (only the fields we read) ─────────────────
type FactorioListMod = { name: string; title: string; summary: string; downloads_count: number; category?: string };
type FactorioListResponse = { results: FactorioListMod[] };

type FactorioLicense = { id?: string; name?: string; title?: string };
type FactorioImage = { thumbnail?: string; url?: string };
type FactorioRelease = { info_json?: { factorio_version?: string }; dependencies?: string[] };
type FactorioFullMod = {
  name: string;
  title: string;
  summary: string;
  description?: string | null;
  category?: string;
  owner: string;
  thumbnail?: string | null;
  images?: FactorioImage[];
  license?: FactorioLicense | null;
  downloads_count: number;
  updated_at?: string;
  releases?: FactorioRelease[];
};

function categoryLabel(cat: string | undefined): string {
  if (!cat || cat === "no-category") return "Mod";
  return cat;
}

function galleryUrlsFrom(images: FactorioImage[] | undefined): string[] {
  return (images ?? [])
    .map((img) => img.thumbnail || img.url)
    .filter((u): u is string => !!u)
    .map((u) => (u.startsWith("http") ? u : `${ASSET_HOST}${u}`))
    .slice(0, GALLERY_CAP);
}

function iconUrlFrom(thumbnail: string | null | undefined): string | null {
  if (!thumbnail) return null;
  return thumbnail.startsWith("http") ? thumbnail : `${ASSET_HOST}${thumbnail}`;
}

function licenseFrom(license: FactorioLicense | null | undefined): string | null {
  if (!license) return null;
  return license.title || license.name || null;
}

function gameVersionsFrom(releases: FactorioRelease[] | undefined): string[] {
  const versions = new Set<string>();
  for (const r of releases ?? []) {
    const v = r.info_json?.factorio_version;
    if (v) versions.add(v);
  }
  return [...versions].sort();
}

type Counters = { total: number; internalExcluded: number; belowFloor: number; eligible: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { total: 0, internalExcluded: 0, belowFloor: 0, eligible: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(
    `[import-factorio-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
      `threshold: downloads>${args.minDownloads}; rate: ${args.ratePerMin}/min${args.maxItems ? `; max-items=${args.maxItems} (smoke test)` : ""}`
  );

  const limiter = new RateLimiter(args.ratePerMin);
  const counters = emptyCounters();

  const listRes = await apiFetch(limiter, `${API}/mods?page_size=max`);
  if (!listRes.ok) {
    console.error(`Refusing to continue: /api/mods returned HTTP ${listRes.status}. Nothing was written.`);
    process.exit(1);
  }
  const list = (await listRes.json()) as FactorioListResponse;
  counters.total = list.results.length;
  console.log(`  fetched ${list.results.length} total mods from the Mod Portal list endpoint`);

  const nonInternal = list.results.filter((m) => m.category !== "internal");
  counters.internalExcluded = list.results.length - nonInternal.length;
  const eligible = nonInternal.filter((m) => m.downloads_count > args.minDownloads);
  counters.belowFloor = nonInternal.length - eligible.length;
  counters.eligible = eligible.length;
  eligible.sort((a, b) => b.downloads_count - a.downloads_count);
  const slice = args.maxItems !== undefined ? eligible.slice(0, args.maxItems) : eligible;
  console.log(
    `  category=internal excluded: ${counters.internalExcluded}; below floor: ${counters.belowFloor}; ` +
      `eligible (downloads>${args.minDownloads}): ${counters.eligible}; processing ${slice.length}`
  );

  const existingRows = await db.gameMod.findMany({
    where: { gameFamily: GAME_FAMILY, source: SOURCE },
    select: { id: true, slug: true, sourceId: true },
  });
  const existingBySourceId = new Map(existingRows.filter((r) => r.sourceId).map((r) => [r.sourceId as string, r]));
  const usedSlugs = new Set(existingRows.map((r) => r.slug));
  console.log(`  ${existingRows.length} existing ${SOURCE} row(s) already in this family`);

  const CONCURRENCY = 5;
  for (let i = 0; i < slice.length; i += CONCURRENCY) {
    const batch = slice.slice(i, i + CONCURRENCY);
    await Promise.all(
      batch.map(async (listMod) => {
        const detailRes = await apiFetch(limiter, `${API}/mods/${encodeURIComponent(listMod.name)}/full`);
        if (!detailRes.ok) {
          counters.failed++;
          console.error(`  [detail] ${listMod.name} → HTTP ${detailRes.status}`);
          return;
        }
        const mod = (await detailRes.json()) as FactorioFullMod;
        if (!mod || !mod.name) {
          counters.failed++;
          console.error(`  [detail] ${listMod.name} → no usable body`);
          return;
        }

        const data = {
          name: mod.title || mod.name,
          category: categoryLabel(mod.category),
          description: mod.summary || null,
          longDescription: mod.description || null,
          iconUrl: iconUrlFrom(mod.thumbnail),
          url: `https://mods.factorio.com/mod/${mod.name}`,
          downloads: mod.downloads_count ?? null,
          license: licenseFrom(mod.license),
          gameVersions: gameVersionsFrom(mod.releases),
          loaders: [] as string[],
          serverSide: null as string | null,
          galleryUrls: galleryUrlsFrom(mod.images),
          authorName: mod.owner || null,
          authorAvatarUrl: null,
          source: SOURCE,
          sourceId: mod.name,
          active: true,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote: null as string | null,
          upstreamUpdatedAt: mod.updated_at ? new Date(mod.updated_at) : null,
        };

        if (!args.apply) {
          counters.upserted++;
          return;
        }

        const existing = existingBySourceId.get(mod.name);
        try {
          if (existing) {
            await db.gameMod.update({ where: { id: existing.id }, data });
            counters.updated++;
          } else {
            let slug = kebab(mod.name);
            for (let attempt = 0; attempt < 3 && usedSlugs.has(slug); attempt++) {
              slug = attempt === 0 ? `${kebab(mod.name)}-${attempt}` : `${kebab(mod.name)}-${attempt}`;
            }
            usedSlugs.add(slug);
            await db.gameMod.create({ data: { gameFamily: GAME_FAMILY, slug, ...data } });
            counters.created++;
          }
          counters.upserted++;
        } catch (e) {
          counters.failed++;
          const msg = e instanceof Error ? e.message : String(e);
          console.error(`  [db] failed to upsert ${listMod.name}: ${msg}`);
        }
      })
    );
    if ((i / CONCURRENCY) % 20 === 0) {
      console.log(
        `  progress: ${Math.min(i + CONCURRENCY, slice.length)}/${slice.length} processed ` +
          `(upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} failed=${counters.failed})`
      );
    }
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  console.log(
    `  factorio total=${counters.total} internalExcluded=${counters.internalExcluded} belowFloor=${counters.belowFloor} ` +
      `eligible=${counters.eligible} processed=${slice.length} upserted=${counters.upserted} created=${counters.created} ` +
      `updated=${counters.updated} failed=${counters.failed}`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

