// ── Vintage Story types (only the fields we read) ────────────────────────
// NOTE: `urlalias` and `modidstrs` are genuinely nullable/emptyable — checked
// live 2026-09-24 against the FULL 8,684-mod list: 3,471 mods (~40%!) have
// `urlalias: null` (an author never set a vanity alias), and 51 of those also
// have an empty `modidstrs`. `modid` (the real numeric id) is the only field
// confirmed unique and present on every single row — see identity strategy
// below.
type VsModSummary = {
  modid: number;
  name: string;
  summary: string | null;
  author: string;
  urlalias: string | null;
  modidstrs?: string[];
  side: "client" | "server" | "both";
  downloads: number;
  logo?: string | null;
};
type VsListResponse = { statuscode: string; mods: VsModSummary[] };

type VsScreenshot = { mainfile: string };
type VsRelease = { tags?: string[] };
type VsModDetail = {
  modid: number;
  name: string;
  text: string | null;
  author: string;
  urlalias: string | null;
  logofile: string | null;
  side: "client" | "server" | "both";
  downloads: number;
  tags: string[];
  releases: VsRelease[];
  screenshots: VsScreenshot[];
};
type VsDetailResponse = { statuscode: string; mod: VsModDetail };

function serverSideFor(side: "client" | "server" | "both"): string | null {
  if (side === "client") return "unsupported";
  return "required";
}

function galleryUrlsFrom(shots: VsScreenshot[] | undefined): string[] {
  return (shots ?? []).slice(0, GALLERY_CAP).map((s) => s.mainfile);
}

function kebab(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60) || ""
  );
}

/**
 * Real slug base for a mod that may have no `urlalias` at all: prefer the
 * author-set vanity alias, else the mod's own programmatic identifier
 * (`modidstrs[0]` — checked live, only 2 collisions across all 8,684 mods,
 * essentially always present and unique), else fall back to a numeric slug
 * built from the one field guaranteed on every row. The caller's existing
 * usedSlugs de-dup loop still runs on top of this as a safety net.
 */
function slugBaseFor(mod: { urlalias: string | null; modidstrs?: string[]; modid: number }): string {
  if (mod.urlalias) return mod.urlalias;
  const fromIdStr = mod.modidstrs?.[0] ? kebab(mod.modidstrs[0]) : "";
  if (fromIdStr) return fromIdStr;
  return `mod-${mod.modid}`;
}

